"use client"

import * as React from "react"

import {
  Dialog,
  DialogClose,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogPanel,
  DialogPopup,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog"
import {
  Drawer,
  DrawerClose,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerPanel,
  DrawerPopup,
  DrawerTitle,
  DrawerTrigger,
} from "@/components/ui/drawer"
import { useIsMobile } from "@/hooks/use-media-query"

type ResponsiveDialogContextValue = {
  isDesktop: boolean
}

const ResponsiveDialogContext =
  React.createContext<ResponsiveDialogContextValue | null>(null)

function useResponsiveDialogContext() {
  const context = React.useContext(ResponsiveDialogContext)

  if (!context) {
    throw new Error(
      "ResponsiveDialog components must be used within <ResponsiveDialog>"
    )
  }

  return context
}

type ResponsiveDialogProps = {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  children: React.ReactNode
  /** Which edge the drawer slides in from on mobile. @defaultValue "bottom" */
  drawerPosition?: "right" | "left" | "top" | "bottom" | "start" | "end"
}

function ResponsiveDialog({
  open,
  defaultOpen,
  onOpenChange,
  children,
  drawerPosition = "bottom",
}: ResponsiveDialogProps) {
  const isMobile = useIsMobile()
  const isDesktop = !isMobile

  const contextValue = React.useMemo(() => ({ isDesktop }), [isDesktop])

  return (
    <ResponsiveDialogContext.Provider value={contextValue}>
      {isDesktop ? (
        <Dialog
          open={open}
          defaultOpen={defaultOpen}
          onOpenChange={onOpenChange}
        >
          {children}
        </Dialog>
      ) : (
        <Drawer
          open={open}
          defaultOpen={defaultOpen}
          onOpenChange={onOpenChange}
          position={drawerPosition}
        >
          {children}
        </Drawer>
      )}
    </ResponsiveDialogContext.Provider>
  )
}

function ResponsiveDialogTrigger(
  props: React.ComponentProps<typeof DialogTrigger>
) {
  const { isDesktop } = useResponsiveDialogContext()
  return isDesktop ? (
    <DialogTrigger {...props} />
  ) : (
    <DrawerTrigger {...(props as React.ComponentProps<typeof DrawerTrigger>)} />
  )
}

function ResponsiveDialogClose(
  props: React.ComponentProps<typeof DialogClose>
) {
  const { isDesktop } = useResponsiveDialogContext()
  return isDesktop ? (
    <DialogClose {...props} />
  ) : (
    <DrawerClose {...(props as React.ComponentProps<typeof DrawerClose>)} />
  )
}

function ResponsiveDialogPopup(
  props: React.ComponentProps<typeof DialogPopup>
) {
  const { isDesktop } = useResponsiveDialogContext()
  return isDesktop ? (
    <DialogPopup {...props} />
  ) : (
    <DrawerPopup {...(props as React.ComponentProps<typeof DrawerPopup>)} />
  )
}

function ResponsiveDialogPanel(
  props: React.ComponentProps<typeof DialogPanel>
) {
  const { isDesktop } = useResponsiveDialogContext()
  return isDesktop ? (
    <DialogPanel {...props} />
  ) : (
    <DrawerPanel {...(props as React.ComponentProps<typeof DrawerPanel>)} />
  )
}

function ResponsiveDialogHeader(
  props: React.ComponentProps<typeof DialogHeader>
) {
  const { isDesktop } = useResponsiveDialogContext()
  return isDesktop ? (
    <DialogHeader {...props} />
  ) : (
    <DrawerHeader {...(props as React.ComponentProps<typeof DrawerHeader>)} />
  )
}

function ResponsiveDialogFooter(
  props: React.ComponentProps<typeof DialogFooter>
) {
  const { isDesktop } = useResponsiveDialogContext()
  return isDesktop ? (
    <DialogFooter {...props} />
  ) : (
    <DrawerFooter {...(props as React.ComponentProps<typeof DrawerFooter>)} />
  )
}

function ResponsiveDialogTitle(
  props: React.ComponentProps<typeof DialogTitle>
) {
  const { isDesktop } = useResponsiveDialogContext()
  return isDesktop ? (
    <DialogTitle {...props} />
  ) : (
    <DrawerTitle {...(props as React.ComponentProps<typeof DrawerTitle>)} />
  )
}

function ResponsiveDialogDescription(
  props: React.ComponentProps<typeof DialogDescription>
) {
  const { isDesktop } = useResponsiveDialogContext()
  return isDesktop ? (
    <DialogDescription {...props} />
  ) : (
    <DrawerDescription
      {...(props as React.ComponentProps<typeof DrawerDescription>)}
    />
  )
}

/**
 * Renders children on desktop only. On mobile the dialog is a bottom drawer
 * users dismiss by swiping down, so a Cancel button is redundant there.
 *
 * Convention: wrap every Cancel/انصراف action in this so it shows on desktop
 * only; keep the confirm/primary action outside so it stays on both. The
 * footer is flex, so the lone primary button fills the width on mobile.
 */
function ResponsiveDialogDesktopOnly({
  children,
}: {
  children: React.ReactNode
}) {
  const { isDesktop } = useResponsiveDialogContext()
  if (!isDesktop) return null
  return <>{children}</>
}

export {
  ResponsiveDialog,
  ResponsiveDialogClose,
  ResponsiveDialogDescription,
  ResponsiveDialogDesktopOnly,
  ResponsiveDialogFooter,
  ResponsiveDialogHeader,
  ResponsiveDialogPanel,
  ResponsiveDialogPopup,
  ResponsiveDialogPopup as ResponsiveDialogContent,
  ResponsiveDialogTitle,
  ResponsiveDialogTrigger,
}

"use client"

import { useCallback, useSyncExternalStore } from "react"

const BREAKPOINTS = {
  "2xl": 1536,
  "3xl": 1600,
  "4xl": 2000,
  lg: 1024,
  md: 800,
  sm: 640,
  xl: 1280,
} as const

type Breakpoint = keyof typeof BREAKPOINTS
type BreakpointQuery =
  Breakpoint | `max-${Breakpoint}` | `${Breakpoint}:max-${Breakpoint}`

function resolveMin(value: Breakpoint | number): string {
  const px = typeof value === "number" ? value : BREAKPOINTS[value]
  return `(min-width: ${px}px)`
}

function resolveMax(value: Breakpoint | number): string {
  const px = typeof value === "number" ? value : BREAKPOINTS[value]
  return `(max-width: ${px - 1}px)`
}

function parseQuery(
  query: BreakpointQuery | MediaQueryInput | (string & {})
): string {
  if (typeof query !== "string") {
    const parts: string[] = []
    if (query.min != null) parts.push(resolveMin(query.min))
    if (query.max != null) parts.push(resolveMax(query.max))
    if (query.pointer === "coarse") parts.push("(pointer: coarse)")
    if (query.pointer === "fine") parts.push("(pointer: fine)")
    if (parts.length === 0) return "(min-width: 0px)"
    return parts.join(" and ")
  }

  if (query.startsWith("(")) return query

  const parts: string[] = []
  for (const segment of query.split(":")) {
    if (segment.startsWith("max-")) {
      const bp = segment.slice(4)
      if (bp in BREAKPOINTS) parts.push(resolveMax(bp as Breakpoint))
    } else if (segment in BREAKPOINTS) {
      parts.push(resolveMin(segment as Breakpoint))
    }
  }

  return parts.length > 0 ? parts.join(" and ") : query
}

function getServerSnapshot(): boolean {
  return false
}

export type MediaQueryInput = {
  min?: Breakpoint | number
  max?: Breakpoint | number
  /** Touch-like input (finger). Use "fine" for mouse/trackpad. */
  pointer?: "coarse" | "fine"
}

/** Tracks a CSS media query with Tailwind-like breakpoint syntax. Returns `false` during SSR. */
export function useMediaQuery(
  query: BreakpointQuery | MediaQueryInput | (string & {})
): boolean {
  const mediaQuery = parseQuery(query)

  const subscribe = useCallback(
    (callback: () => void) => {
      if (typeof window === "undefined") return () => {}
      const mql = window.matchMedia(mediaQuery)
      mql.addEventListener("change", callback)
      return () => mql.removeEventListener("change", callback)
    },
    [mediaQuery]
  )

  const getSnapshot = useCallback(() => {
    if (typeof window === "undefined") return false
    return window.matchMedia(mediaQuery).matches
  }, [mediaQuery])

  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot)
}

export function useIsMobile(): boolean {
  return useMediaQuery("max-md")
}
